let cards=[],sets=[],glyphs=[];
function canvas(w,h){return new OffscreenCanvas(Math.max(1,Math.round(w)),Math.max(1,Math.round(h)))}
function pixels(source,x=0,y=0,w=source.width,h=source.height,sw=w,sh=h){const c=canvas(sw,sh),ctx=c.getContext('2d',{willReadFrequently:true});ctx.drawImage(source,x,y,w,h,0,0,c.width,c.height);return ctx.getImageData(0,0,c.width,c.height).data}
function components(mask,w,h){const seen=new Uint8Array(w*h),stack=new Int32Array(w*h),out=[];for(let start=0;start<mask.length;start++){if(!mask[start]||seen[start])continue;let size=1;stack[0]=start;seen[start]=1;let l=w,r=0,t=h,b=0,count=0;while(size){const i=stack[--size],x=i%w,y=Math.floor(i/w);count++;l=Math.min(l,x);r=Math.max(r,x);t=Math.min(t,y);b=Math.max(b,y);for(const n of [x?i-1:-1,x<w-1?i+1:-1,y?i-w:-1,y<h-1?i+w:-1])if(n>=0&&mask[n]&&!seen[n]){seen[n]=1;stack[size++]=n}}out.push({x:l,y:t,w:r-l+1,h:b-t+1,count})}return out}
function findCards(image){const w=image.width,h=image.height,p=pixels(image),mask=new Uint8Array(w*h);for(let i=0;i<mask.length;i++)mask[i]=Math.max(p[i*4],p[i*4+1],p[i*4+2])<65?1:0;return components(mask,w,h).filter(b=>b.w>w*.17&&b.w<w*.31&&b.h/b.w>1.3&&b.h/b.w<1.8&&b.y>h*.16&&b.y+b.h<h*.94).sort((a,b)=>b.w-a.w).filter((b,i,all)=>!all.slice(0,i).some(a=>Math.abs(a.x-b.x)<w*.05&&Math.abs(a.y-b.y)<w*.05)).sort((a,b)=>Math.round(a.y/(w*.09))-Math.round(b.y/(w*.09))||a.x-b.x).map(b=>({...b,y:b.y+b.h-b.w*834/582,h:b.w*834/582}))}
function artCost(p,ref){let err=0,n=0;for(let y=8;y<68;y+=2)for(let x=6;x<58;x+=2){if(y>57&&x>40)continue;const k=(y*64+x)*4;if(ref[k+3]<160)continue;for(let c=0;c<3;c++)err+=((p[k+c]-ref[k+c])/255)**2;n+=3}return err/Math.max(1,n)}
function identifyCard(image,box){const p=pixels(image,box.x,box.y,box.w,box.h,64,92);return cards.map(c=>({number:c.number,set:c.set,cost:artCost(p,c.data)})).sort((a,b)=>a.cost-b.cost).slice(0,3)}
function identifySet(image,first){const candidates=[];for(const s of sets){let best=Infinity;for(const scale of [1,1.05,1.1])for(const dx of [-.02,.02])for(const dy of [-.02,.02]){const size=first.w*scale,p=pixels(image,first.x+first.w*(.27+dx),first.y-first.w*(1.28-dy),size,size,96,96);let error=0,n=0;for(let y=10;y<86;y+=3)for(let x=10;x<86;x+=3){const k=(y*96+x)*4;if(s.data[k+3]<200)continue;for(let c=0;c<3;c++)error+=((p[k+c]-s.data[k+c])/255)**2;n+=3}best=Math.min(best,error/n)}candidates.push({set:s.number,cost:best})}return candidates.sort((a,b)=>a.cost-b.cost)}
function isBack(image,box){const p=pixels(image,box.x+box.w*.15,box.y+box.h*.22,box.w*.7,box.h*.45,32,40);let orange=0,texture=0;for(let i=0;i<1280;i++){const r=p[i*4],g=p[i*4+1],b=p[i*4+2];if(r>155&&g>65&&g<200&&b<115&&r>g*1.15)orange++;if(i%32&&Math.abs(r-p[(i-1)*4])+Math.abs(g-p[(i-1)*4+1])+Math.abs(b-p[(i-1)*4+2])>80)texture++}return {ratio:orange/1280,texture:texture/1280,readable:orange/1280>.76&&texture/1280<.35}}
function readCount(image,box){const cw=Math.round(box.w*.205),ch=Math.round(box.h*.095),p=pixels(image,box.x+box.w*.765,box.y+box.h*.67,cw,ch),mask=new Uint8Array(cw*ch),cols=new Uint8Array(cw);let dark=0;for(let yy=0;yy<ch;yy++)for(let xx=0;xx<cw;xx++){const k=(yy*cw+xx)*4;const white=Math.min(p[k],p[k+1],p[k+2])>155&&Math.max(p[k],p[k+1],p[k+2])-Math.min(p[k],p[k+1],p[k+2])<80;if(Math.max(p[k],p[k+1],p[k+2])<90)dark++;if(white){mask[yy*cw+xx]=1;cols[xx]=1}}if(dark/(cw*ch)<.45)return {value:1,readable:true,badge:false,dark:dark/(cw*ch)};
 const spans=[];let start=null;for(let xx=0;xx<=cw;xx++){if(cols[xx]&&start===null)start=xx;if(!cols[xx]&&start!==null){let top=ch,bottom=0;for(let yy=0;yy<ch;yy++)for(let x=start;x<xx;x++)if(mask[yy*cw+x]){top=Math.min(top,yy);bottom=Math.max(bottom,yy)}spans.push({x:start,y:top,w:xx-start,h:bottom-top+1});start=null}}
 let text='',worst=0,margin=Infinity;const debug=[];for(const span of spans){if(span.h<ch*.3)continue;const c=canvas(span.w,span.h),ctx=c.getContext('2d'),im=ctx.createImageData(span.w,span.h);for(let yy=0;yy<span.h;yy++)for(let xx=0;xx<span.w;xx++){const k=(yy*span.w+xx)*4;im.data[k+3]=mask[(span.y+yy)*cw+span.x+xx]*255}ctx.putImageData(im,0,0);const values=pixels(c,0,0,span.w,span.h,16,24),scores=new Map();for(const g of glyphs){let e=0;for(let i=0;i<384;i++)e+=((values[i*4+3]-g.values[i])/255)**2;e=e/384+.12*Math.abs(span.w/span.h-g.aspect);scores.set(g.char,Math.min(scores.get(g.char)??Infinity,e))}const rank=[...scores].sort((a,b)=>a[1]-b[1]);text+=rank[0][0];worst=Math.max(worst,rank[0][1]);margin=Math.min(margin,rank[1][1]-rank[0][1]);debug.push({span,rank:rank.slice(0,2)})}
 const clean=text.replace(/^x/,'');return {value:/^[1-9][0-9]{0,2}$/.test(clean)?Number(clean):null,readable:/^x[1-9][0-9]{0,2}$/.test(text)&&worst<.24&&margin>.004,badge:true,text,worst,margin,debug,dark:dark/(cw*ch)}}
async function scan(image){const originalScale=image.width/591;if(image.width!==591){const normalized=canvas(591,image.height*591/image.width);const ctx=normalized.getContext('2d');ctx.imageSmoothingQuality='high';ctx.drawImage(image,0,0,normalized.width,normalized.height);image=normalized;}const boxes=findCards(image);if(boxes.length!==9)return {cards:[],reason:'Use a screenshot showing one complete 3×3 album set.',boxes};const matched=boxes.map(b=>identifyCard(image,b)),votes=new Map();for(let i=0;i<9;i++){const best=matched[i][0];if(best.cost<.12&&(best.number-1)%9===i)votes.set(best.set,(votes.get(best.set)||0)+1)}const ranked=[...votes].sort((a,b)=>b[1]-a[1]),badge=identifySet(image,boxes[0]),set=ranked[0]?.[1]>=3?ranked[0][0]:(badge[0].cost<.09&&badge[1].cost-badge[0].cost>.025?badge[0].set:null);if(!set)return {cards:[],reason:'Album set could not be confirmed.',boxes,matched,badge:badge.slice(0,2)};const out=[];for(let i=0;i<9;i++){const number=(set-1)*9+i+1,match=matched[i].find(m=>m.number===number),back=isBack(image,boxes[i]),count=readCount(image,boxes[i]);let badgeCost=null;if(match){const ref=cards.find(c=>c.number===number).data,p=pixels(image,boxes[i].x,boxes[i].y,boxes[i].w,boxes[i].h,64,92);let err=0,n=0;for(let y=62;y<73;y++)for(let x=48;x<61;x++){const k=(y*64+x)*4;for(let c=0;c<3;c++)err+=((p[k+c]-ref[k+c])/255)**2;n+=3}badgeCost=err/n;}count.artDifference=badgeCost;if(!count.readable&&badgeCost!==null&&badgeCost<.008){count.value=1;count.readable=true;count.badge=false;count.artConfirmed=true;}const missing=back.readable&&(!match||match.cost>.10),owned=!!match&&match.cost<.12&&!back.readable;out.push({number,set,box:{x:boxes[i].x*originalScale,y:boxes[i].y*originalScale,w:boxes[i].w*originalScale,h:boxes[i].h*originalScale},quantity:missing?0:count.value,readable:missing||(owned&&count.readable),owned,missing,match:matched[i],back,count,reason:missing?'Missing':!owned?'Card artwork could not be confirmed.':!count.readable?'Copy count is unclear.':null});self.postMessage({type:'progress',done:i+1,total:9})}return {set,cards:out,badge:badge.slice(0,2)}}
self.onmessage=async({data})=>{try{if(data.type==='load'){const a=await createImageBitmap(data.atlas),s=await createImageBitmap(data.setAtlas);cards=data.references.cards.map(c=>({...c,data:pixels(a,c.x,c.y,64,92)}));sets=data.references.sets.map(c=>({...c,data:pixels(s,c.x,c.y,96,96)}));glyphs=data.references.glyphs;a.close();s.close();self.postMessage({type:'ready'})}else if(data.type==='scan'){try{self.postMessage({type:'result',...await scan(data.image)})}finally{data.image.close()}}}catch(e){self.postMessage({type:'error',message:e.message})}};
